section.sourcecode:
UpdateTTL(iph,n)
struct ip_hdr *ipptr;
unsigned char n;
{
    unsigned long sum;
    unsigned short old;

    old = ntohs(*(unsigned short *)&ipptr->ttl);
    ipptr->ttl -= n;
    sum = old + (~ntohs(*(unsigned short *)&ipptr->ttl) & 0xffff);
    sum += ntohs(ipptr->Checksum);
    sum = (sum & 0xffff) + (sum>>16);
    ipptr->Checksum = htons(sum + (sum>>16));
}
